import 'package:flutter/material.dart';
import '../widgets/common.dart';

class PainelResponsavelScreen extends StatelessWidget {
  const PainelResponsavelScreen({super.key});
  @override
  Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Vínculo com responsável')), body: ContentFrame(child: ListView(padding: const EdgeInsets.all(24), children: [const Icon(Icons.family_restroom_outlined, size: 64), const SizedBox(height: 20), Text('Proteção em família', style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height: 12), const Text('Esta tela informa a situação do vínculo. A administração do responsável exige conta e autenticação próprias, ainda dependentes da integração do provedor.'), const SizedBox(height: 24), FutureBuilder<Map<String,dynamic>>(future: AppScope.of(context).api.request('GET','/guardian/status'), builder: (_,s) => s.hasError ? Text(s.error.toString()) : !s.hasData ? const Center(child: CircularProgressIndicator()) : Card(child: Padding(padding: const EdgeInsets.all(20), child: Text(s.data!['approved'] == true ? 'Vínculo verificado' : s.data!['required'] == true ? 'Aguardando verificação do responsável. O provedor não está configurado.' : 'Esta conta é adulta.')))), const SizedBox(height: 16), FilledButton(onPressed: () async { try { final result = await AppScope.of(context).api.request('POST','/guardian/request'); if (context.mounted) showFeedback(context,result['message']!); } catch(e) { if (context.mounted) showFeedback(context,e); } }, child: const Text('Registrar pedido de vínculo')), const SizedBox(height: 20), const Text('Não coletamos imagens faciais e não mostramos conversas privadas ao responsável. Nenhum botão nesta tela concede aprovação.')])));
}
